package top.dcpstudios.calendarwidget;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;

/** Same RemoteViews layout and selection model on launcher and in-app. */
final class AttentionCards {
 static final class Card {String label,title,body,footer,uid="",id="";long message;boolean transientCard,arrivalAction;Card(String l,String t,String b,String f){label=l;title=t;body=b;footer=f;}}
 static List<Card> cards(Context c){long now=System.currentTimeMillis();List<Card> out=new ArrayList<>();android.content.SharedPreferences p=TerminalClient.prefs(c);
  long seen=p.getLong("cards_seen",0);for(JSONObject m:TerminalDb.get(c).messages("")){JSONObject payload=m.optJSONObject("payload");if(m.optLong("id")<=seen||!m.optBoolean("notify")||m.optBoolean("is_read"))continue;String source=m.optString("source");boolean urgent=payload!=null&&"重要".equals(payload.optString("message_kind"));if(!urgent&&!source.equals("canvas")&&!source.equals("schedule"))continue;Card card=new Card(urgent?"紧急消息":"新的待办",m.optString("title"),m.optString("body"),(source.equals("wechat")?"微信":source.equals("canvas")?"Canvas":"日程助手")+" · "+CalendarData.format(m.optLong("occurred_at")));card.message=m.optLong("id");card.transientCard=true;out.add(card);if(out.size()>=6)break;}
  JSONObject state=AttentionSettings.state(c);long until=state.optLong("summary_until");if(until>now&&until!=p.getLong("summary_seen",0)){JSONObject s=state.optJSONObject("summary");if(s!=null){Card card=new Card("消息总结","刚才有 "+s.optInt("total")+" 条暂缓消息",s.optInt("chats")+" 个会话 · 点击查看消息","回到正常状态 · 五分钟内可见");card.id="summary";card.transientCard=true;out.add(card);}}
  Card next=nextClass(c,now);if(next!=null&&!next.id.equals(p.getString("arrived","")))out.add(next);
  List<CalendarData.Event> events=CalendarData.visible(CalendarStore.read(c),now,false,false);StringBuilder body=new StringBuilder();int count=0;for(CalendarData.Event e:events){if(e.completed)continue;if(count++<2){if(body.length()>0)body.append('\n');body.append(e.title);}}
  Card todo=new Card("待办",count==0?"现在，专注当下":count+" 项待办",body.length()==0?"暂时没有待完成的任务":body.toString(),CalendarStore.status(c));todo.id="todo";out.add(todo);return out;
 }
 static Card nextClass(Context c,long now){Card best=null;long earliest=Long.MAX_VALUE;for(JSONObject event:TerminalDb.get(c).schedules()){long start=event.optLong("start_at"),end=event.optLong("end_at");if(!"active".equals(event.optString("status"))||end<=now||start>=earliest)continue;earliest=start;best=scheduleCard(event.optString("title"),event.optString("location"),event.optString("id"),start,end,now);}return best;}
 static Card scheduleCard(String title,String location,String uid,long start,long end,long now){boolean ongoing=start<=now,soon=!ongoing&&start-now<=3600000;long minutes=Math.max(1,(start-now)/60000),remaining=Math.max(1,(end-now)/60000);Calendar time=Calendar.getInstance(TimetableData.ZONE);time.setTimeInMillis(start);Calendar today=Calendar.getInstance(TimetableData.ZONE);today.setTimeInMillis(now);for(Calendar value:new Calendar[]{time,today}){value.set(Calendar.HOUR_OF_DAY,0);value.set(Calendar.MINUTE,0);value.set(Calendar.SECOND,0);value.set(Calendar.MILLISECOND,0);}long day=(time.getTimeInMillis()-today.getTimeInMillis())/86400000L;time.setTimeInMillis(start);String when=day==0?"今天":day==1?"明天":String.format(Locale.CHINA,"%d月%d日",time.get(Calendar.MONTH)+1,time.get(Calendar.DAY_OF_MONTH));String clock=String.format(Locale.CHINA,"%02d:%02d",time.get(Calendar.HOUR_OF_DAY),time.get(Calendar.MINUTE));Card card=new Card(ongoing?"正在进行":soon?"即将开始":"下一日程",location.isEmpty()?title:location,title,ongoing?"还有 "+remaining+" 分钟结束 · 点击查看日程":soon?"还有 "+minutes+" 分钟 · 点击到达":when+" "+clock+" · 点击查看日程");card.uid=uid;card.id=uid+"-"+start;card.arrivalAction=soon;return card;}
 static Intent intent(Context c,Card card){Intent i=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);if(card.message>0)i.putExtra("messageId",card.message);else if(card.id.equals("summary"))i.putExtra("page","messages");else i.putExtra("page","agenda");return i;}
 static RemoteViews view(Context c,Card card,int request){if("todo".equals(card.id))return CalendarWidget.todoViews(c,request);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.attention_card);v.setInt(R.id.card_root,"setBackgroundResource",dark(c)?R.drawable.attention_background_dark:R.drawable.attention_background);v.setTextColor(R.id.card_title,ink(c));v.setTextColor(R.id.card_body,muted(c));v.setTextColor(R.id.card_label,muted(c));v.setTextColor(R.id.card_footer,muted(c));v.setTextColor(R.id.card_action,dark(c)?0xFF83CBB6:0xFF25796C);v.setTextViewText(R.id.card_label,card.label);v.setTextViewText(R.id.card_title,card.title);v.setTextViewText(R.id.card_body,card.body);v.setTextViewText(R.id.card_footer,card.footer);v.setOnClickPendingIntent(R.id.card_root,PendingIntent.getActivity(c,request,intent(c,card),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));if(!card.uid.isEmpty()){v.setTextViewText(R.id.card_action,card.arrivalAction?"到达 ✓":"查看日程");if(card.arrivalAction)v.setOnClickPendingIntent(R.id.card_action,PendingIntent.getBroadcast(c,request,new Intent(c,CalendarWidget.class).setAction("DCP_ARRIVED").putExtra("arrival",card.id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));else v.setOnClickPendingIntent(R.id.card_action,PendingIntent.getActivity(c,request+10000,intent(c,card),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}return v;}
 static boolean dark(Context c){String theme=CalendarStore.prefs(c).getString("theme","system");return "dark".equals(theme)||("system".equals(theme)&&(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);}
 static int ink(Context c){return dark(c)?0xFFE9F0EC:0xFF172C31;}
 static int muted(Context c){return dark(c)?0xFFA8B5B4:0xFF596C70;}
 static android.view.View appView(MainActivity a,Card card,int request,android.view.ViewGroup parent){
  if(!"todo".equals(card.id))return view(a,card,request).apply(a,parent);
  android.view.View box=a.getLayoutInflater().inflate(R.layout.widget,parent,false);box.setBackgroundResource(dark(a)?R.drawable.attention_background_dark:R.drawable.attention_background);
  for(int id:new int[]{R.id.title,R.id.widget_status,R.id.widget_empty,R.id.widget_refresh})((TextView)box.findViewById(id)).setTextColor(id==R.id.title?ink(a):muted(a));
  ((TextView)box.findViewById(R.id.widget_status)).setText(CalendarStore.status(a));((TextView)box.findViewById(R.id.widget_empty)).setText("目前没有待办");ListView list=box.findViewById(R.id.widget_list);WidgetListService.Rows rows=new WidgetListService.Rows(a);rows.onDataSetChanged();list.setAdapter(new BaseAdapter(){public int getCount(){return rows.getCount();}public Object getItem(int n){return rows.rows.get(n);}public long getItemId(int n){return n;}public android.view.View getView(int n,android.view.View old,android.view.ViewGroup p){return rows.getViewAt(n).apply(a,p);}});list.setEmptyView(box.findViewById(R.id.widget_empty));list.setOnItemClickListener((p,v,n,id)->a.detail(rows.rows.get(n)));box.findViewById(R.id.title).setOnClickListener(v->a.agenda());box.findViewById(R.id.widget_refresh).setOnClickListener(v->a.refresh());return box;
 }
 static void opened(Context c){android.content.SharedPreferences p=TerminalClient.prefs(c);long summary=AttentionSettings.state(c).optLong("summary_until");p.edit().putLong("cards_seen",p.getLong("cursor",0)).putLong("opened_at",System.currentTimeMillis()).putLong("summary_seen",summary).apply();CalendarWidget.renderAll(c);if(NetDiskSession.canTerminal(c))TerminalClient.IO.execute(()->{try{TerminalClient.request(c,"/attention/opened",new JSONObject().put("summary_until",summary));}catch(Exception ignored){}});}
}
